public class Main {
  static void update(int[] arr) {
    for (int i = 0; i < arr.length; i++) {
      arr[i] *= 2;
    }
  }
  public static void main(String[] args) {
    int[] nums = {1, 2, 3, 4};
    update(nums);
    int sum = 0;
    for (int n : nums) sum += n;
    System.out.print(sum);
  }
}
